<script>
$(function(){const f=$('[data-sales-intake-form]'), d={{ $decimals }}, step={{ 1 / (10 ** $decimals) }}, tax=@json($taxOptions); let n=$('[data-line]').length;
function money(v){return Number(v||0).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});}
function inputNumber(v){return v===''||v===null||v===undefined?'':Number(v).toFixed(d);}
function applyPrecision($scope){$scope.find('.js-qty,.js-price,.js-discount').attr({type:'number',min:0,step:step}).each(function(){this.value=inputNumber(this.value);});}
function itemSelect(i){return `<select class="form-select js-item" name="lines[${i}][item_id]" data-defaults-url="{{ route('pos.sales-intakes.item-defaults') }}"></select>`;}
function promotionSelect(i){return `<select class="form-select js-line-promotion" name="lines[${i}][promotion_id]" data-url="{{ route('pos.sales-intakes.promotion-options') }}"><option value="">— ไม่ใช้ Promotion —</option></select>`;}
function row(i){let opts=tax.map(t=>`<option value="${t.id}" data-rate="${t.rate}">${t.code} · ${t.name}</option>`).join('');return `<tr data-line><td class="sales-intake-item-cell">${itemSelect(i)}<input class="form-control mt-2" name="lines[${i}][description]" placeholder="รายละเอียดรายการ"><input type="hidden" name="lines[${i}][uom_id]" class="js-uom-id"><small class="text-secondary js-uom-text"></small></td><td>${promotionSelect(i)}</td><td><span class="form-control-plaintext js-uom-label"></span></td><td><input class="form-control text-end js-qty" name="lines[${i}][quantity]" value="1" required></td><td><input class="form-control text-end js-price" name="lines[${i}][requested_unit_price]"></td><td><input class="form-control text-end js-discount" name="lines[${i}][discount_amount]" value="0"></td><td><select class="form-select js-tax-code" name="lines[${i}][tax_code_id]" disabled><option value="">ไม่มี VAT</option>${opts}</select></td><td class="text-end fw-semibold js-line-total">${money(0)}</td><td><button type="button" class="btn btn-sm btn-outline-danger" data-remove-line title="ลบรายการ">🗑</button></td></tr>`;}
function applyPromotion(r){let p=r.find('.js-line-promotion'),o=p.find('option:selected'),active=!!p.val();r.find('.js-price,.js-discount').prop('readonly',active);if(active){r.find('.js-price').val(inputNumber(o.data('unit-price')));r.find('.js-discount').val(inputNumber(o.data('discount-amount')));}totals();}
function loadPromotion($select,scope){let r=$select.closest('tr'),party=$('.js-party').val(),data={party_id:party,document_date:f.find('[name=document_date]').val(),scope:scope};if(scope==='LINE'){data.item_id=r.find('.js-item').val();data.quantity=r.find('.js-qty').val();}if(!party||(scope==='LINE'&&(!data.item_id||!data.quantity))){$select.find('option:not(:first)').remove();return;}let current=$select.data('selected')||$select.val();$.get($select.data('url'),data).done(v=>{$select.find('option:not(:first)').remove();(v.results||[]).forEach(x=>$select.append($('<option>').val(x.id).text(x.text).data('unit-price',x.unit_price).data('discount-amount',x.discount_amount)));$select.val(current&&$select.find(`option[value="${current}"]`).length?current:'').removeData('selected');if(scope==='LINE')applyPromotion(r);});}
function refreshPromotions(){loadPromotion($('.js-document-promotion'),'DOCUMENT');$('.js-line-promotion').each(function(){loadPromotion($(this),'LINE');});}
function initItem(el){$(el).select2({width:'100%',placeholder:'ค้นหาสินค้า',templateSelection:data=>$('<span>',{text:data.text||'',title:data.text||''}),ajax:{url:'{{ route('pos.sales-intakes.item-options') }}',dataType:'json',delay:250,data:p=>({q:p.term,page:p.page}),processResults:r=>r}}).on('select2:select',function(e){let r=$(this).closest('tr'),x=e.params.data;r.find('.js-uom-id').val(x.uom_id||'');r.find('.js-uom-label,.js-uom-text').text(x.uom_text||'');$.get($(this).data('defaults-url'),{item_id:x.id,party_id:$('.js-party').val(),document_date:f.find('[name=document_date]').val(),quantity:r.find('.js-qty').val()}).done(v=>{if(v.standard_price!==null)r.find('.js-price').val(inputNumber(v.standard_price));}).always(()=>loadPromotion(r.find('.js-line-promotion'),'LINE'));});}
$('.js-party').select2({width:'100%',placeholder:'ค้นหาลูกค้า',ajax:{url:'{{ route('pos.sales-intakes.party-options') }}',dataType:'json',delay:250,data:p=>({q:p.term,page:p.page}),processResults:r=>r}});$('.js-item').each((_,e)=>initItem(e));applyPrecision(f);
function loadAddresses(partyId,preserve){let current={billing:$('.js-billing-address').data('current')||'',shipping:$('.js-shipping-address').data('current')||''};$('.js-billing-address,.js-shipping-address,.js-quick-address').prop('disabled',true);$('.js-billing-address,.js-shipping-address').empty().append('<option>กำลังโหลดที่อยู่...</option>');if(!partyId)return;$.get('{{ route('pos.sales-intakes.party-addresses') }}',{party_id:partyId}).done(data=>{$.each(['billing','shipping'],(_,type)=>{let $select=$('.js-'+type+'-address'),saved=preserve?current[type]:'';$select.empty().append('<option value="">— ไม่ระบุ —</option>');$.each(data[type]||[],(_,address)=>$select.append($('<option>').val(address.value).text(address.text).prop('selected',saved?address.value===saved:address.is_default)));if(saved&&!$select.find('option').filter(function(){return $(this).val()===saved;}).length)$select.append($('<option selected>').val(saved).text('ที่อยู่เดิม · '+saved));$select.prop('disabled',false);});$('.js-quick-address').prop('disabled',false);}).fail(()=>$('.js-billing-address,.js-shipping-address').empty().append('<option value="">โหลดที่อยู่ไม่สำเร็จ</option>').prop('disabled',false));}
$('.js-party').on('change',function(){loadAddresses($(this).val(),false);refreshPromotions();});if($('.js-party').val()){loadAddresses($('.js-party').val(),true);refreshPromotions();}
@if(auth()->user()->hasPermission('pos.customers.create'))
let quickCustomerTimer,quickCustomerRequest=0;
function useQuickCustomer(customer){$('.js-party').append(new Option(customer.text,customer.id,true,true)).trigger('change');bootstrap.Modal.getInstance(document.getElementById('quick-customer-modal')).hide();}
function quickCustomerMatches(response){let form=$('#quick-customer-form'),box=form.find('[data-quick-customer-matches]').empty(),save=form.find('[type=submit]').prop('disabled',!!response.hard_match);if(!(response.results||[]).length)return box.addClass('d-none');box.removeClass('d-none').append($('<div class="alert mb-0 py-2"></div>').addClass(response.hard_match?'alert-warning':'alert-info').text(response.hard_match?'พบข้อมูลที่มีรหัสหรือเลขภาษีตรงกัน กรุณาใช้ข้อมูลเดิม':'พบลูกค้าที่คล้ายกัน โปรดตรวจสอบก่อนบันทึก'));response.results.forEach(customer=>{let row=$('<div class="d-flex justify-content-between align-items-center gap-2 border-top pt-2 mt-2"></div>').append($('<span></span>').text(customer.text));if(customer.can_select)row.append($('<button class="btn btn-sm btn-app-soft js-use-existing-customer" type="button">เลือก</button>').data('customer',customer));box.append(row);});}
function checkQuickCustomer(){let form=$('#quick-customer-form'),data=form.serialize(),request=++quickCustomerRequest;if(!form.find('[name=name],[name=tax_id],[name=phone],[name=email]').filter(function(){return this.value.trim();}).length){form.find('[data-quick-customer-matches]').empty().addClass('d-none');form.find('[type=submit]').prop('disabled',false);return;}$.get('{{ route('pos.customers.quick-options') }}',data).done(response=>{if(request===quickCustomerRequest)quickCustomerMatches(response);});}
$('.js-quick-customer').on('click',()=>{let form=$('#quick-customer-form');form[0].reset();form.find('[data-quick-customer-matches]').empty().addClass('d-none');form.find('[type=submit]').prop('disabled',false);bootstrap.Modal.getOrCreateInstance(document.getElementById('quick-customer-modal')).show();});
$('#quick-customer-form').on('input change','[name=name],[name=tax_id],[name=phone],[name=email]',function(){clearTimeout(quickCustomerTimer);quickCustomerTimer=setTimeout(checkQuickCustomer,250);}).on('click','.js-use-existing-customer',function(){useQuickCustomer($(this).data('customer'));}).on('submit',function(e){e.preventDefault();let form=$(this),button=form.find('[type=submit]').prop('disabled',true);$.post('{{ route('pos.customers.store') }}',form.serialize()).done(response=>{useQuickCustomer(response.customer);form[0].reset();}).fail(xhr=>Swal.fire({icon:'error',title:'เพิ่มลูกค้าไม่สำเร็จ',text:xhr.responseJSON?.message||Object.values(xhr.responseJSON?.errors||{}).flat()[0]||'กรุณาตรวจสอบข้อมูล'})).always(()=>button.prop('disabled',false));});
@endif
@if(auth()->user()->hasPermission('pos.customers.update'))
$('.js-quick-address').on('click',function(){let form=$('#quick-address-form');form[0].reset();form.find('[name=address_type]').val($(this).data('type'));bootstrap.Modal.getOrCreateInstance('#quick-address-modal').show();});
$('#quick-address-form').on('submit',function(e){e.preventDefault();let form=$(this),partyId=$('.js-party').val(),button=form.find('[type=submit]').prop('disabled',true);$.post('{{ route('pos.customers.addresses.store', ['customer' => '__customer__']) }}'.replace('__customer__',partyId),form.serialize()).done(response=>{let type=response.address.type.toLowerCase();$('.js-'+type+'-address').data('current',response.address.value);loadAddresses(partyId,true);bootstrap.Modal.getInstance(document.getElementById('quick-address-modal')).hide();}).fail(xhr=>Swal.fire({icon:'error',title:'เพิ่มที่อยู่ไม่สำเร็จ',text:xhr.responseJSON?.message||Object.values(xhr.responseJSON?.errors||{}).flat()[0]||'กรุณาตรวจสอบข้อมูล'})).always(()=>button.prop('disabled',false));});
@endif
function taxMode(){let vat=$('.js-tax-calculation').val()!=='NONE';$('.js-tax-code').prop('disabled',!vat);if(!vat)$('.js-tax-code').val('');else $('.js-tax-code').each(function(){if(!this.value&&tax[0])this.value=tax[0].id;});}$('.js-tax-calculation').on('change',taxMode);taxMode();
$(document).on('click','[data-add-line]',()=>{$('[data-lines]').append(row(n++));let $line=$('[data-line]').last();initItem($line.find('.js-item'));applyPrecision($line);taxMode();});$(document).on('click','[data-remove-line]',function(){if($('[data-line]').length>1)$(this).closest('tr').remove();});$(document).on('change','.js-line-promotion',function(){applyPromotion($(this).closest('tr'));}).on('change','.js-qty',function(){loadPromotion($(this).closest('tr').find('.js-line-promotion'),'LINE');}).on('change','[name=document_date]',refreshPromotions);
function totals(){let s=0,disc=0,baseTotal=0,taxv=0,mode=$('.js-tax-calculation').val();$('.js-line-total').each(function(){let r=$(this).closest('tr'),q=Number(r.find('.js-qty').val()||0),p=Number(r.find('.js-price').val()||0),x=Number(r.find('.js-discount').val()||0),rate=Number(r.find('.js-tax-code option:selected').data('rate')||0),gross=Math.max(0,q*p-x),base=mode==='VAT_INCLUSIVE'&&rate?gross*100/(100+rate):gross,t=mode==='NONE'?0:gross-base;s+=q*p;disc+=x;baseTotal+=base;taxv+=t;$(this).text(money(gross+(mode==='VAT_EXCLUSIVE'?t:0)));});$('[data-subtotal]').text(money(s));$('[data-discount]').text(money(disc));$('[data-tax-base]').text(money(baseTotal));$('[data-tax]').text(money(taxv));$('[data-grand-total]').text(money(baseTotal+taxv));}f.on('input change','.js-qty,.js-price,.js-discount,.js-tax-code,.js-tax-calculation',totals);totals();window.erpAjaxForm({form:'[data-sales-intake-form]',redirect:{{ $intake->exists ? 'false' : 'true' }}});});
</script>
